<?php require_once __DIR__.'/../includes/auth.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$st=$pdo->prepare('SELECT id,name,sku,quantity FROM products WHERE id=?');$st->execute([$id]);$p=$st->fetch();if(!$p){flash('error','Product not found.');redirect('index.php');}$pageTitle='Adjust stock';$base='/shop-inventory-management';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$change=filter_var($_POST['quantity_change']??null,FILTER_VALIDATE_INT);$reason=trim($_POST['reason']??'');if($change===false||$change===0)$error='Enter a non-zero whole-number adjustment (positive to add, negative to remove).';elseif($reason==='')$error='Please provide a reason.';else{$pdo->beginTransaction();try{$st=$pdo->prepare('SELECT quantity FROM products WHERE id=? FOR UPDATE');$st->execute([$id]);$current=(int)$st->fetchColumn();if($current+$change<0){$pdo->rollBack();$error='This adjustment would make stock negative.';}else{$st=$pdo->prepare('UPDATE products SET quantity=quantity+? WHERE id=?');$st->execute([$change,$id]);audit_stock($pdo,$id,$change,$reason,$_SESSION['user_id']);$pdo->commit();flash('success','Stock adjusted successfully.');redirect('index.php');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not adjust stock. Please retry.';}}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Adjust stock</h1><p>Record stock received, damaged items, corrections or other changes.</p></div><a class="btn" href="index.php">← Back to inventory</a></div><div class="panel form-panel"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="stock-summary"><span>Product</span><strong><?=e($p['name'])?></strong><span>SKU <?=e($p['sku'])?></span><span>Current stock</span><strong><?=$p['quantity']?> units</strong></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Quantity change *<input name="quantity_change" type="number" step="1" required placeholder="e.g. 10 or -2"><small class="help">Use a positive number to add stock, or a negative number to remove stock.</small></label><label>Reason *<select name="reason" required><option value="">Choose a reason</option><option>Stock received</option><option>Damaged goods</option><option>Stock correction</option><option>Return to supplier</option><option>Other adjustment</option></select></label><div class="form-actions"><button class="btn primary">Save adjustment</button><a class="btn" href="index.php">Cancel</a></div></form></div><?php require __DIR__.'/../includes/footer.php';?>
